        return null;
    }
    return (
        <ToolbarTooltip content={info} wrap pinOnClick>
            <span
                className="git-graph-anchored-dialog-info"
                onMouseDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                }}
            >
                <span className="codicon codicon-info" aria-hidden />
            </span>
        </ToolbarTooltip>
    );
}

function renderFieldInfo(info?: string) {
    return <FieldInfo info={info} />;
}

function renderAnchoredFormFields(
    fields: FormField[],
    formValues: Record<string, string>,
    onFormValuesChange: (values: Record<string, string>) => void,
    onSubmit: () => void,
    submitWhenEnter?: () => boolean,
) {
    return (
        <table className="git-graph-anchored-dialog-form">
            <tbody>
                {fields.map((field) => {
                    if (field.type === 'text') {
                        return (
                            <tr key={field.id}>
                                <th scope="row">{field.label}:</th>
                                <td>
                                    <input
                                        type="text"
                                        className="git-graph-anchored-dialog-input"
                                        placeholder={field.placeholder}
                                        value={formValues[field.id] ?? ''}
                                        autoFocus={field.id === fields[0]?.id}
                                        onChange={(e) => {
                                            onFormValuesChange({
                                                ...formValues,
                                                [field.id]: e.target.value,
                                            });
                                        }}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && (!submitWhenEnter || submitWhenEnter())) {
                                                e.preventDefault();
                                                onSubmit();
                                            }
                                        }}
                                    />
